# number, alias, selector, explanation. A selector is a function or inclusive lines.
SOURCES={
1:[('receipt','fn:check','先读路径拼接，再看 artifacts 列表推导式。任一文件不存在或摘要变化进入 bad；最后 passed 还要求原 automated_status 是 PASS。这个函数返回新判断，不改旧回执。调用者 require 在不满足时抛错，因此结果为 PARTIAL 与文件变更是两个独立失败维度。'),('record','1:18','CASES 是普通字典，spec 字段声明任务范围。declared_scope_matches 将外部回执、实际 spec 与声明逐项比较，防止三点录像被误标为完整任务。这里没有执行模型推理，只是在核对事实合同。')],
2:[('entry','1:30','set 的选项影响 shell 错误行为；r_base 通过脚本自身路径计算。source 在当前 shell 加载环境，exec 替换 shell，最后的 "$@" 保留参数边界。把这些词按顺序解释，比死记启动命令更容易迁移目录。')],
3:[('runtime','fn:run','run 是进程编排入口。先生成本次输出与绑定，再准备 env 和日志，后续通过子进程句柄持续检查并统一收尾。节选只展示函数开头；完整源码中寻找 Popen、finally、SIGINT 与 wait，区分启动成功和任务成功。'),('env','1:30','unset 清理会冲突的旧 overlay，随后 source Jazzy 和当前工作区。这里只设置子进程环境，不安装软件。ROS_DOMAIN_ID 与 GZ_PARTITION 分属 ROS 和 Gazebo 通信域，不应混为一个变量。')],
4:[('rig','fn:effective_rig','deepcopy 保留原标定字典。update 只改变明确的采样与版本信息；canonical 对剔除旧 revision 后的内容计算新标识。函数返回派生配置，不直接移动任何车体。'),('precision','1:45','const 引用避免修改输入；at 在必需字段缺失时失败；value 为可选字段提供默认。检查授权 scope、数字类型、有限性和距离范围后，才返回受界限约束的精停进展尺度。')],
5:[('action','1:45','两个分隔线之前是请求，中间是结果，之后是反馈。uint8 常量给操作编号，字符串字段绑定版本与工作身份，float64 记录数量和时间。消息结构描述传输，不自动实现业务门控。'),('mission','22:47','main 创建节点、ActionClient 与订阅，将状态保存到 st。lambda 的 k=key 固定循环键；事件日志把阶段和仿真时间串起来。ActionClient 的类型决定协议，任务函数再决定什么时候发送或取消。')],
6:[('recovery','fn:validate_candidate','先检查端点和姿态，再把导航点转换到 world 检查授权足迹。曲率用弦长和角差估计，插值补充两端之间扫掠。函数最后只声明先验与运动学通过，明确实时观测风险仍需另检。')],
7:[('sensor','fn:__init__','此处选择 Adapter.__init__。两个 Context 分别进入原始域与在线域，发布器只输出明确观测，motion/vision 分支限制负载。它是受控跨域适配，不是任务节点随意读取真值。'),('receipt','fn:seal','seal 保存 summary、来源文件与制品摘要。next_step 只在 summary 通过时提供；formal_credit 固定 false，原 S17/S18 PARTIAL 明确保留。写出回执是记录结论，不是替实验提供证据。')],
8:[('precision','1:45','与样章已有解读一致，保留一个独立可编译的真实判据入口。这个函数只返回距离尺度，不能独自证明超时、碰撞或工具反馈正确。')],
9:[('world','fn:geometries','Polygon 从不规则顶点构造，面积缩放使用平方根，因为面积随线性尺度平方变化；translate 放到指定中心。两个三次 Bézier 段生成连接中心线，再 buffer 成道路区域。此函数属于离线世界生成，不能当在线感知入口。'),('world','fn:part','同一 geometry 可以分别写 visual 与 collision。collision=False 只改变可见外观，不影响物理接触；这正是理解贴图和碰撞模型分离的入口。')],
10:[('drive','80:114','v,w 先限幅，阿克曼零速不允许转圈。k=w/v 被最大曲率限制，左右转角按轴距与轮距分别计算；转向误差大时降低车速。最后用反馈转角计算实际曲率，再映射四个关节命令。')],
11:[('sensor','fn:enqueue','延迟队列保存到期时间、序号、消息、大小和采集时间；bytes 约束内存，heapq 先取最早到期项。入队后立即 flush 允许零延迟数据及时发出。'),('sensor','fn:flush','flush 不重写消息 header。若某采集时刻不比已发布的新，则记录 late_discard。传输恢复后的旧包不能倒退在线时间；丢弃统计是质量证据的一部分。'),('sensor','fn:imu','随机游走按 sqrt(dt) 增长，角速度与加速度分别加偏置和白噪声。姿态被声明不可用，协方差用 sigma 平方。代码末尾继续走统一延迟队列，而不是绕开时间模型。')],
12:[('icp','fn:emit','emit 先读实际 RTAB quality，检查失锁、内点率、协方差、几何与运动跳变。只有合格历史窗口才生成 base_link 速度增量。发布质量日志与发布可融合消息是分开的，拒绝样本也留下原因。'),('cloud','fn:geometry','cKDTree 找近邻，协方差最小特征向量估计表面法向，再统计法向二阶矩特征值。最小值很小时某些方向信息弱；它是观测几何指标，不能直接等同真实定位误差。')],
13:[('export','fn:export','只读 SQLite integrity_check 先检查数据库；graph_probe 与 rtabmap-export 使用外部真实工具。导出前后数据库摘要必须一致，manifest 把观察来源与所有文件绑定。export 不是把 SDF 世界几何直接当作 SLAM 输出。')],
14:[('regional','42:83','点云按采集时间配 odom，粗初始化多航向尝试，候选分歧和跟踪修正超限会拒绝。GNSS 部分先变换到 ENU，加入旋转杆臂，再计算 residual 与 NIS；valid 是这些条件的交集。'),('correction','1:40','Eigen::Isometry3d 同时保存旋转和平移，allFinite 拒绝坏矩阵。alpha 用 expm1 提高小 dt 数值稳定性，旋转用四元数 slerp 再归一。调用者必须在此之前检查原始异常。')],
15:[('surface','1:45','z 分位统计来自射线而非简单体素计数。high/low 按小平面格收集独立支持，至少三个返回且置信区间分离才保留小表面模式。strong 危险通道优先，不被平均稀释。'),('self','1:30','physical 是真实车体内部，padded 是带余量区域。外环只删除满足高度条件的返回，低地面仍保留。这个函数是过滤判据，不会给缺失区域制造自由空间。')],
16:[('tracker','fn:update','先做短时状态预测，再构造距离/NIS/尺寸代价；匈牙利分配后仍检查歧义。匹配成功更新状态与命中次数，超过丢失时间删除，输出时保留 observed_age 与 confirmed。'),('leader','26:46','把轨迹转到 map，投影到当前路径弧长；沿向速度与横向速度决定同向关系。gap 扣除目标大小和车体前伸；只有新鲜观测与有效路径才形成可用证据。')],
17:[('imm','fn:transition','同一个六维状态在 CV、CA 与左右转弯下使用不同 F。CA 包含 dt²/2 和加速度积分；转弯矩阵使用 sin/cos 表达协调转动。这是运动模型候选，不包含未来标签。'),('memory','fn:predict','observe 消费当下历史，context/Trigger 决定事件，lookup 仅影响是否调用学习模型。命中后仍调用当前 IMM predict；wall/cpu 与 feature/query/maintenance/inference 分项累计，防止只统计节省的调用数。')],
18:[('metis','25:73','CSR 输入验证包括数组长度、整数范围、无重复对称边和输入连通。opts 设置 CONTIG、seed 与 UFACTOR，再调用真实 METIS。返回 labels 后检查每簇非空；车辆几何仍归 Python 后验。'),('partition','fn:metis','Python 将 CSR 和整数权重序列化为 JSON，运行已构建后端并检查退出码。这个边界让 C++ 负责图算法、Python 负责几何与报告，输出文件不是自动可信输入。')],
19:[('planning','fn:visibility','可见图用合法区域 covers 判断整条线，随后对每个服务节点运行 Dijkstra。heapq 保存当前最短候选，prev 反向恢复点间路径。所有服务点相互可达才返回代价矩阵。'),('planner','fn:tsp','RoutingIndexManager 负责内部索引映射，回调返回整数代价，时间上限限制搜索。optimality_claimed=false 明确不把启发式解当全局证明。')],
20:[('planner','20:32','Fields2Cover 先构造工作与通行几何，枚举方向并用整区同相位生成 swaths，再排序。decomposition 用于描述几何分解，不意味着每个簇独立生成不同相位。'),('safe','fn:validate','校验原作业多边形与面积、时间预算和通行权限，再检查整条执行路径连续、单挡、曲率与包络。连接段不能带工具或面积信用，工作段保持原 work_key 与 target。')],
21:[('mission','22:47','三种客户端分别处理导航到点、短路径和工具动作。类型和名称决定要连接哪个 server，实际动作等待/取消在后续 helper 中实现。先读接口，再读状态转换，不从客户端存在推断每个分支都已执行。'),('nav','1:34','controller_plugins 当前只列 RPP；goal/progress checker 分别管理到达和进展。下面仍有 DWB 参数块，但未列入当前插件名单，属于保留配置而非同时运行。')],
22:[('precision','1:45','这个短函数是完整生产判据，可以由教材 C++ 例直接调用。所有合法性检查失败时回退粗尺度，只有受界限保护的局部精停才缩小进展阈值；未修改超时与安全条件。'),('nav','88:114','RPP 参数说明前视、接近降速、碰撞检查与反向行驶。use_rotate_to_heading=false 适配阿克曼不能原地旋转；allow_reversing=true 还需外部单挡段和停车流程配合。')],
23:[('tree','1:40','XML 的顺序就是优先级，ReactiveFallback 每次重新检查高优先级条件。末尾 Execute 只是写出任务选择，长动作由 mission 执行。节点 SUCCESS 不等于整个工作区完成。'),('policy','18:49','prepare 维护阻塞和进展时间，leader/detour/replan/defer/exhausted 分别判断资格。choose 同时保存证据、阈值和所有候选资格，使日志能解释没有选中的原因。')],
24:[('mowing','125:141','START_WORK 请求后保存活动句柄与结果 Future，wait_startup 在等待真实反馈时也检查 BT。中断进入 stop_all 并返回 False；只有有效成功或工作反馈才继续。'),('recovery','fn:gear_runs','位移投影到中点航向得到挡位；明显侧向位移被拒绝。符号改变时结束旧 run 并共享尖点。这个函数只切路径，真正换挡还必须由门控确认车与工具停止。')],
25:[('ledger','fn:reserve','reserve 检查版本、能力与目标，工作键查重后比较目标指纹。SUCCEEDED 返回 replayed，uncertain 拒绝自动重试；BEGIN IMMEDIATE 将任务预留与状态变迁原子提交。'),('ledger','fn:observe','observe 按事件身份去重，检查时间、上下文、序号与工具健康，再按连续反馈积剂量或几何面积。事件和工作量在同一事务写入；失败也记录 reason，便于解释为什么没有信用。')],
26:[('cmake','1:35','find_package 解析编译依赖，add_library 构造 Gazebo 共享插件，target_link_libraries 链接真实库，install 决定运行时位置。Python pip 不能替代这里的系统 ABI 与 CMake 包。'),('env','1:30','环境脚本重置 overlay 并加载 Jazzy，运行它不安装地图、虚拟环境或编译库。新机器需要分别准备这几层；当前机 source 后的 check 也只验证回执绑定范围。')],
27:[('record','1:18','案例字典明确点数/段数/时间，完整案例用 limit=0 表达全范围。读取此声明能防止误把默认短例当完整簇。额外启动故障案例在后续赋值加入，AST 练习同时读取。'),('record','fn:record','record 先 require R09，再检查派生源码摘要，按案例调用 runtime，并分别分析任务与视频。最终 passed 是任务、编码、时间线和图像质量交集，video_valid 不能单独升级任务。')],
28:[('guidata','fn:freshness','函数区分无 stamp、时间不合法、过期与有效。新鲜度是观测条件，不是任务成功。界面字段应保留 source 和会话，避免历史快照被误当实时。'),('gui','40:75','GET 路由聚合数据或返回相机，run 身份必须匹配。服务先占端口再起 observer，finally 关闭自己的子进程；没有控制命令接口，因此当前 GUI 是只读。')],
29:[('toolbuild','fn:generate_tool','派生器定位原 C++ 接收逻辑，将反馈入队并在时钟追上后消费。保留 arrival 用于墙钟年龄，不重新打采集戳。字符串断言用于发现上游源码变化，不能静默生成错误派生版本。'),('receipt','fn:check','失败复验前先查内容是否仍匹配回执。某阶段 status 为 PASS 但 bound 文件 changed，也不能复用为当前证据。这个短函数是版本问题与行为问题分开的入口。')],
30:[('safe','fn:load_checked','加载时重算计划 revision，再核对参考计划、后端二进制、后端源码、生成器与包络源码摘要。几何修改会使多个依赖失效，不能只改一个 JSON 的 revision。'),('receipt','fn:seal','最终保存的 summary 与制品集合形成新的可追溯证据。next_step 由当前真实结论决定，原正式状态不会因学习或演示完成而自动升级。')],
}

PARTS=[(1,4,'项目问题与学习基础'),(5,8,'ROS 与完整系统'),(9,11,'世界 车辆与传感器'),(12,17,'定位与三维感知'),(18,22,'规划与导航控制'),(23,25,'决策与有效作业'),(26,28,'部署与人工实验'),(29,30,'调试与自主研究')]
